        public T Post<T, Y>(Y obj)
        {
            ServicePointManager.SecurityProtocol = SecurityProtocolType.Tls12;

            HttpWebRequest myHttpWebRequest = (HttpWebRequest)WebRequest.Create(_baseUrl);
            myHttpWebRequest.Method = "POST";
            myHttpWebRequest.ContentType = "text/xml";
            myHttpWebRequest.Timeout = 1000 * 1000;
            myHttpWebRequest.Headers.Add("Authorization", "Basic " + base.GetAuthHeader(_username, _password));

            Console.WriteLine(myHttpWebRequest.RequestUri.ToString());

            HttpWebResponse myHttpWebResponse;

            string xmlString = obj.ToXML<Y, Y>();
            byte[] byteArray = Encoding.ASCII.GetBytes(xmlString);

            myHttpWebRequest.ContentLength = byteArray.Length;

            Stream newStream = myHttpWebRequest.GetRequestStream();
            newStream.Write(byteArray, 0, byteArray.Length);
            newStream.Close();

            try
            {
                myHttpWebResponse = (HttpWebResponse)myHttpWebRequest.GetResponse();
            }
            catch (Exception ex)
            {
                Console.WriteLine($"{myHttpWebRequest.RequestUri.ToString()}{Environment.NewLine}{ex.ToString()}");
                return default(T);
            }

            string responseText = "";

            using (var reader = new System.IO.StreamReader(myHttpWebResponse.GetResponseStream()))
            {
                responseText = reader.ReadToEnd();
            }

            myHttpWebResponse.Close();

            return responseText.ToObject<T>();
        }

